"""Brute-force solvers + tests comparing 3-SAT answers to reduced IS answers."""

from __future__ import annotations

import itertools
import random

from problems import ThreeSat, IndependentSet
from reduce import reduce


# --------------------------- brute force solvers ---------------------------

def solve_three_sat(instance: dict) -> bool:
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for bits in itertools.product([False, True], repeat=m):
        # variable v (1..m) -> bits[v-1]
        ok = True
        for clause in clauses:
            if not any(
                (bits[abs(lit) - 1] if lit > 0 else not bits[abs(lit) - 1])
                for lit in clause
            ):
                ok = False
                break
        if ok:
            return True
    return False


def solve_independent_set(instance: dict) -> bool:
    n = instance["n"]
    k = instance["k"]
    if k <= 0:
        return True
    if k > n:
        return False
    adj = [set() for _ in range(n)]
    for u, v in instance["edges"]:
        adj[u].add(v)
        adj[v].add(u)
    # brute force over all subsets of size >= k (small n)
    for size in range(k, n + 1):
        for subset in itertools.combinations(range(n), size):
            s = set(subset)
            if all(not (adj[u] & s) for u in subset):
                return True
    return False


# ------------------------------- generators --------------------------------

def random_three_sat(rng: random.Random, max_vars: int, max_clauses: int) -> dict:
    m = rng.randint(0, max_vars)
    if m < 3:
        # clauses need m >= 3, so only the empty-clause formula is possible
        return {"num_vars": m, "clauses": []}
    nclauses = rng.randint(0, max_clauses)
    clauses = []
    for _ in range(nclauses):
        vs = rng.sample(range(1, m + 1), 3)
        clause = [v if rng.random() < 0.5 else -v for v in vs]
        clauses.append(clause)
    return {"num_vars": m, "clauses": clauses}


def all_small_three_sat():
    """Exhaustive small formulas: m in 0..3, all clause sets over a tiny space."""
    # m = 0..2: only empty clause list is valid
    for m in range(0, 3):
        yield {"num_vars": m, "clauses": []}
    # m = 3: enumerate formulas with up to 2 clauses from all possible clauses
    m = 3
    possible = []
    for vs in itertools.permutations(range(1, 4), 3):
        for signs in itertools.product([1, -1], repeat=3):
            possible.append([s * v for s, v in zip(signs, vs)])
    # dedupe as unordered clauses
    uniq = []
    seen = set()
    for c in possible:
        key = frozenset(c)
        if key not in seen:
            seen.add(key)
            uniq.append(c)
    yield {"num_vars": m, "clauses": []}
    for c in uniq:
        yield {"num_vars": m, "clauses": [c]}
    for c1, c2 in itertools.combinations(uniq, 2):
        yield {"num_vars": m, "clauses": [c1, c2]}


# ---------------------------------- tests ----------------------------------

def main() -> None:
    tests_run = 0
    tests_passed = 0

    def check(src: dict) -> None:
        nonlocal tests_run, tests_passed
        tests_run += 1
        ThreeSat.validate(src)
        tgt = reduce(src)
        IndependentSet.validate(tgt)
        expected = solve_three_sat(src)
        got = solve_independent_set(tgt)
        if expected == got:
            tests_passed += 1
        else:
            print("MISMATCH")
            print("  src     :", src)
            print("  expected:", expected)
            print("  tgt     :", tgt)
            print("  got     :", got)

    # exhaustive small cases
    for src in all_small_three_sat():
        check(src)

    # random cases
    rng = random.Random(12345)
    for _ in range(400):
        check(random_three_sat(rng, max_vars=5, max_clauses=4))

    # explicit edge cases
    check({"num_vars": 0, "clauses": []})
    check({"num_vars": 7, "clauses": []})
    check({"num_vars": 3, "clauses": [[1, 2, 3]]})
    check({"num_vars": 3, "clauses": [[1, 2, 3], [1, 2, 3]]})
    check({"num_vars": 4, "clauses": [[1, 2, 3], [-1, -2, -3], [1, -2, 4]]})
    # unsatisfiable: all 8 clauses over 3 vars
    unsat = []
    for vs in itertools.permutations(range(1, 4), 3):
        for signs in itertools.product([1, -1], repeat=3):
            unsat.append([s * v for s, v in zip(signs, vs)])
    check({"num_vars": 3, "clauses": unsat})

    print(f"tests_run={tests_run} tests_passed={tests_passed}")
    assert tests_run == tests_passed, "some tests failed"

    import json
    with open("verdict.json", "w") as f:
        json.dump({"verified": True, "tests_run": tests_run, "tests_passed": tests_passed}, f)
    print("verdict.json written")


if __name__ == "__main__":
    main()
